style.css:
@-moz-document domain("web.whatsapp.com") {
/* Paleta de colores Hot Rod G1 */
    :root {
        --hr-red: #c8102e;
        --hr-magenta: #e6005c;
        --hr-orange: #ff5e00;
        --hr-yellow: #ffcc00;
        --hr-dark: #14090c;
        --hr-panel: #1f0e13;
        --hr-surface: #2d141b;
    }

    /* Fondo principal y barra superior */
    body, ._aigs {
        background-color: var(--hr-dark) !important;
        color: #f5f5f5 !important;
    }

    /* Lista de chats y paneles laterales */
    #pane-side, header, ._ak72, ._ak8l {
        background-color: var(--hr-panel) !important;
        border-color: var(--hr-red) !important;
    }

    /* Hover y chat seleccionado */
    ._ak72:hover {
        background-color: var(--hr-surface) !important;
    }

    [aria-selected="true"] ._ak72 {
        background: linear-gradient(90deg, var(--hr-red) 0%, var(--hr-surface) 100%) !important;
        border-left: 4px solid var(--hr-yellow) !important;
    }

    /* Fondo del área de conversación con degradado sutil estilo llamas */
    [data-asset-chat-background-dark], [data-asset-chat-background-light] {
        background: radial-gradient(circle at bottom right, #3a0d16 0%, #14090c 75%) !important;
        opacity: 1 !important;
    }

    /* Burbujas de mensajes ENVIADOS (Degradado Rojo a Magenta Hot Rod) */
    .message-out ._amk4, .message-out ._amk6 {
        background: linear-gradient(135deg, var(--hr-red) 0%, var(--hr-magenta) 100%) !important;
        color: #ffffff !important;
        border: 1px solid var(--hr-orange) !important;
        box-shadow: 0 2px 6px rgba(255, 94, 0, 0.25) !important;
    }

    /* Burbujas de mensajes RECIBIDOS (Gris oscuro metálico con borde amarillo) */
    .message-in ._amk4, .message-in ._amk6 {
        background-color: var(--hr-surface) !important;
        color: #ffffff !important;
        border-left: 3px solid var(--hr-yellow) !important;
    }

    /* Nombres de contactos y acentos */
    span[dir="auto"] {
        color: #f8f8f8 !important;
    }

    /* Barra de escritura de mensajes */
    footer, ._ak1r, ._ak1q {
        background-color: var(--hr-panel) !important;
        border-top: 1px solid var(--hr-orange) !important;
    }

    /* Cuadro de texto donde escribes */
    [contenteditable="true"] {
        background-color: var(--hr-surface) !important;
        color: #ffffff !important;
        border-radius: 8px !important;
    }

    /* Iconos y botones activos (Amarillo dorado / Naranja) */
    svg path {
        fill: var(--hr-yellow) !important;
    }

    /* Barra de desplazamiento (Scrollbar) */
    ::-webkit-scrollbar-thumb {
        background: linear-gradient(var(--hr-orange), var(--hr-yellow)) !important;
        border-radius: 4px !important;
    }
    ::-webkit-scrollbar-track {
        background: var(--hr-dark) !important;
    }
}
